// ─── File: src/main/java/com/bank/recon/service/ReconciliationService.java ───
package com.bank.recon.service;

import com.bank.recon.dto.ReconReport;
import com.bank.recon.exception.ReconciliationException;
import com.bank.recon.model.ExchangeTrade;
import com.bank.recon.model.InternalTrade;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;

@Service
@Slf4j
public class ReconciliationService {

    private final List<ExchangeTrade> exchangeTrades = List.of(
        new ExchangeTrade("EX-001", "RELIANCE", new BigDecimal("245050"), "RECEIVED"),
        new ExchangeTrade("EX-002", "TCS", new BigDecimal("176000"), "RECEIVED"),
        new ExchangeTrade("EX-003", "HDFC", new BigDecimal("330150"), "RECEIVED")
    );

    private final List<InternalTrade> internalTrades = List.of(
        new InternalTrade("INT-001", "SAV2001", "RELIANCE", new BigDecimal("245050"), "PENDING"),
        new InternalTrade("INT-002", "SAV2001", "TCS", new BigDecimal("176500"), "PENDING"),
        new InternalTrade("INT-003", "CUR3001", "HDFC", new BigDecimal("330150"), "PENDING")
    );

    // Map internal trades by symbol for lookup
    private final Map<String, InternalTrade> internalBySymbol;

    public ReconciliationService() {
        internalBySymbol = new HashMap<>();
        for (var trade : internalTrades) {
            internalBySymbol.put(trade.symbol(), trade);
        }
    }

    public ReconReport reconcile() {
        List<String> unnamedUsages = new ArrayList<>();
        List<String> mismatchDetails = new ArrayList<>();
        int matched = 0;
        int mismatched = 0;
        BigDecimal totalMatched = BigDecimal.ZERO;

        for (ExchangeTrade exTrade : exchangeTrades) {

            // ═══ UNNAMED PATTERN 1: Record destructuring — only need amount ═══
            // We only care about the amount for comparison. tradeId, symbol, status = unused.
            // Java 22+: case ExchangeTrade(var _, var symbol, var amount, var _)
            // For now demonstrating the concept:
            BigDecimal exAmount = exTrade.amount();    // extract just what we need
            String exSymbol = exTrade.symbol();

            InternalTrade internal = internalBySymbol.get(exSymbol);
            if (internal == null) {
                unnamedUsages.add("No internal match for exchange symbol: " + exSymbol);
                continue;
            }

            // ═══ UNNAMED PATTERN 2: catch block — exception variable unused ═══
            try {
                validateAmounts(exAmount, internal.amount(), exSymbol);
                matched++;
                totalMatched = totalMatched.add(exAmount);
                log.info("(Recommended) Matched: {} — Rs.{}", exSymbol, exAmount);
            } catch (ReconciliationException _) {
                // _ = we don't need the exception object — we log our own context message
                mismatched++;
                mismatchDetails.add(exSymbol + ": exchange Rs." + exAmount
                    + " vs internal Rs." + internal.amount());
                log.warn("(Avoid) Mismatch: {} — exchange Rs.{} vs internal Rs.{}",
                    exSymbol, exAmount, internal.amount());
            }
        }

        // ═══ UNNAMED PATTERN 3: for-loop — counting without using element ═══
        int unmatchedExchangeCount = 0;
        List<String> unmatchedSymbols = exchangeTrades.stream()
            .map(ExchangeTrade::symbol)
            .filter(s -> !internalBySymbol.containsKey(s))
            .toList();
        for (var _ : unmatchedSymbols) {
            unmatchedExchangeCount++;
            // We only need the count — the actual symbol is unused in this loop
        }

        // ═══ UNNAMED PATTERN 4: Map.forEach — key unused ═══
        Map<String, BigDecimal> mismatchAmounts = new HashMap<>();
        for (var detail : mismatchDetails) {
            mismatchAmounts.put(detail, BigDecimal.ONE);  // simplified
        }
        mismatchAmounts.forEach((_, amount) -> {
            // We only process the amount — key is unnamed
            log.debug("Mismatch amount marker: {}", amount);
        });

        unnamedUsages.add("catch (ReconciliationException _) — exception var unused, intent clear");
        unnamedUsages.add("for (var _ : unmatchedSymbols) — loop var unused, just counting");
        unnamedUsages.add("map.forEach((_, amount) -> ...) — key unused in lambda");
        unnamedUsages.add("case Trade(var _, var _, var amount, var _) — only amount needed");

        return new ReconReport(matched, mismatched, unmatchedExchangeCount,
            totalMatched, mismatchDetails, unnamedUsages);
    }

    private void validateAmounts(BigDecimal exchange, BigDecimal internal, String symbol)
            throws ReconciliationException {
        if (exchange.compareTo(internal) != 0) {
            throw new ReconciliationException(
                "Amount mismatch for " + symbol + ": " + exchange + " vs " + internal);
        }
    }
}
