// ─── File: src/test/java/com/bank/recon/service/UnnamedVariableTest.java ───
package com.bank.recon.service;

import org.junit.jupiter.api.Test;
import java.io.IOException;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class UnnamedVariableTest {

    // ═══ CATCH: exception variable unused ═══
    @Test
    void catchWithUnnamedVariable() {
        String result;
        try {
            throw new IOException("file not found");
        } catch (IOException _) {
            // _ = we don't read the exception — we handle the error our own way
            result = "HANDLED";
        }
        assertThat(result).isEqualTo("HANDLED");
    }

    // ═══ FOR-LOOP: loop variable unused (just counting) ═══
    @Test
    void forLoopWithUnnamedVariable() {
        List<String> items = List.of("A", "B", "C", "D", "E");
        int count = 0;
        for (var _ : items) {
            count++;
        }
        assertThat(count).isEqualTo(5);
    }

    // ═══ LAMBDA: unused parameter ═══
    @Test
    void lambdaWithUnnamedParameter() {
        Map<String, Integer> map = Map.of("RELIANCE", 100, "TCS", 50);
        List<Integer> values = new ArrayList<>();

        map.forEach((_, value) -> values.add(value));  // key is unnamed

        assertThat(values).containsExactlyInAnyOrder(100, 50);
    }

    // ═══ MULTIPLE _ in same scope — no conflict ═══
    @Test
    void multipleUnnamedInSameScope() {
        // Two catch blocks with _ — no conflict
        try {
            throw new RuntimeException("first");
        } catch (RuntimeException _) {
            // first _ — fine
        }

        try {
            throw new RuntimeException("second");
        } catch (RuntimeException _) {
            // second _ — also fine, no conflict with first _
        }
    }

    // ═══ TRY-WITH-RESOURCES: resource variable unused ═══
    @Test
    void tryWithResourcesUnnamed() {
        // When you open a resource just for its side effect (lock, connection)
        // but don't reference the variable:
        // try (var _ = acquireLock()) { doWork(); }
        // The lock is held for the try block and released on exit.

        // Simulated with AutoCloseable:
        var closed = new java.util.concurrent.atomic.AtomicBoolean(false);
        try (var _ = (AutoCloseable) () -> closed.set(true)) {
            assertThat(closed.get()).isFalse();  // still open
        } catch (Exception e) { /* ignore */ }
        assertThat(closed.get()).isTrue();  // auto-closed!
    }
}
